-- NEW supplementary whole technical Nutrition chain. Original small/full fixtures unchanged.
-- Requires applied base + additive canonical IDs + planned inspection followups.
-- Privileged synthetic isolated fixtures, no HTTP/clinical/professional acceptance.
BEGIN;
SET LOCAL statement_timeout='15s';
SET LOCAL lock_timeout='5s';
DO $unit$
DECLARE
 t uuid:=gen_random_uuid();c uuid:=gen_random_uuid();u uuid:=gen_random_uuid();r uuid:=gen_random_uuid();s uuid:=gen_random_uuid();
 plan_id uuid:=gen_random_uuid();version_id uuid:=gen_random_uuid();item_id uuid:=gen_random_uuid();tour_id uuid:=gen_random_uuid();stop_id uuid:=gen_random_uuid();assessment_id uuid:=gen_random_uuid();
 capture_id uuid:=gen_random_uuid();care_id uuid:=gen_random_uuid();
 day date:=(clock_timestamp()AT TIME ZONE 'Europe/Berlin')::date-1;instant timestamptz;at_text text;
 context jsonb;native_before jsonb;capture_packet jsonb;capture_receipt jsonb;capture_confirmed jsonb;
 entry jsonb;packet jsonb;receipt jsonb;confirmed jsonb;field text;finished boolean:=false;
 reviewer uuid:=gen_random_uuid();review_session uuid:=gen_random_uuid();review_id uuid:=gen_random_uuid();review_packet jsonb;review_receipt jsonb;review_confirmed jsonb;review_page jsonb;review_tail jsonb;care_page jsonb;care_tail jsonb;prerequisites jsonb;bad jsonb;claims text;message text;alias_denials integer:=0;clinical_denials integer:=0;
BEGIN
 BEGIN
  IF to_regprocedure('care_private.nutrition_guard_canonical_wire_ids()')IS NULL THEN RAISE EXCEPTION 'Installed additive canonical guard required';END IF;
  INSERT INTO public.tenants(id,name)VALUES(t,'Synthetic Nutrition linked planning inspection unit');
  INSERT INTO public.roles(id,key,name)VALUES(r,'synthetic_nutrition_small_'||r,'Synthetic Nutrition planning author');
  INSERT INTO public.role_permissions(role_id,permission_key)SELECT r,unnest(ARRAY['pflege.plans.view','pflege.plans.manage','pflege.documentation.view','pflege.documentation.create','pflege.vitals.view','pflege.documentation.sign']);
  INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data)VALUES(u,u||'@example.invalid','{}','{}');
  UPDATE public.profiles SET tenant_id=t,role_id=r,role_key='pfleger',is_active=true,status='active',display_name='Synthetic Nutrition small author'WHERE id=u;
  INSERT INTO auth.sessions(id,user_id,not_after)VALUES(s,u,clock_timestamp()+interval '1 hour');
  INSERT INTO public.clients(id,tenant_id,first_name,last_name,status,lifecycle_status)VALUES(c,t,'Synthetic','Nutrition small case','aktiv','aktiv');
  INSERT INTO public.client_module_assignments(tenant_id,client_id,module_key,status,is_active)VALUES(t,c,'pflege','active',true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','session_id',s,'exp',extract(epoch FROM clock_timestamp()+interval '1 hour')::bigint)::text,true);
  IF auth.uid()IS DISTINCT FROM u OR public.resolve_current_profile_id()IS DISTINCT FROM u OR public.current_tenant_id()IS DISTINCT FROM t THEN RAISE EXCEPTION 'Synthetic actual own Auth/profile/tenant not established';END IF;
  INSERT INTO public.care_plans(id,tenant_id,client_id,title,status,valid_from,valid_until)VALUES(plan_id,t,c,'Synthetic explicit Nutrition planning','aktiv',day-1,day+7);
  INSERT INTO public.care_plan_items(id,tenant_id,care_plan_id,category,title,intervention,status,sort_order,created_by,updated_by)
   VALUES(item_id,t,plan_id,'drink_protocol','Synthetic explicitly planned drink support','Synthetic authored planning, no actual intake','active',1,u,u);
  INSERT INTO public.care_plan_versions(id,tenant_id,care_plan_id,version,snapshot,reason,actor_id,actor_name)
   SELECT version_id,t,plan_id,1,jsonb_build_object('plan',to_jsonb(p),'items',(SELECT jsonb_agg(to_jsonb(i)ORDER BY i.id)FROM public.care_plan_items i WHERE i.care_plan_id=plan_id)),'Synthetic exact full native plan snapshot',u,'Synthetic Nutrition small author'FROM public.care_plans p WHERE p.id=plan_id;
  INSERT INTO public.care_tours(id,tenant_id,tour_date,name,status,created_by,updated_by)VALUES(tour_id,t,day,'Synthetic published Nutrition small tour','published',u,u);
  INSERT INTO public.care_tour_stops(id,tenant_id,tour_id,sequence_no,client_id,client_name_snapshot,planned_start,planned_end,status)
   VALUES(stop_id,t,tour_id,1,c,'Synthetic Nutrition small case','12:15:30.123456','12:45:30.123456','planned');
  INSERT INTO public.care_assessments(id,tenant_id,subject_type,subject_id,subject_name_snapshot,variant,status,version,assessor_profile_id,assessor_name_snapshot,created_by,updated_by)
   VALUES(assessment_id,t,'client',c,'Synthetic Nutrition small case','ambulant','draft',1,u,'Synthetic Nutrition small author',u,u);
  instant:=(day+time '12:15:30.123456')AT TIME ZONE 'Europe/Berlin';
  at_text:=to_char(instant AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  context:=public.web_read_nutrition_elimination_binding_context(t,c,u,version_id,item_id,stop_id,assessment_id);
  SELECT jsonb_build_object('plan',(SELECT to_jsonb(x)FROM public.care_plans x WHERE x.id=plan_id),'planVersion',(SELECT to_jsonb(x)FROM public.care_plan_versions x WHERE x.id=version_id),'measure',(SELECT to_jsonb(x)FROM public.care_plan_items x WHERE x.id=item_id),'visit',(SELECT to_jsonb(x)FROM public.care_tour_stops x WHERE x.id=stop_id),'tour',(SELECT to_jsonb(x)FROM public.care_tours x WHERE x.id=tour_id),'assessment',(SELECT to_jsonb(x)FROM public.care_assessments x WHERE x.id=assessment_id),'assessmentTopics','[]'::jsonb,'assessmentRisks','[]'::jsonb,'assessmentMeasures','[]'::jsonb,'instrumentSelection',null,'model',null,'instruments','[]'::jsonb)INTO native_before;
  IF context->'nativeOriginals'IS DISTINCT FROM native_before OR(context->>'planSnapshotSha256'~'^sha256:[a-f0-9]{64}$')IS NOT TRUE OR context#>'{sources,devices}'IS DISTINCT FROM '[]'::jsonb OR context#>'{sources,protocols}'IS DISTINCT FROM '[]'::jsonb OR context#>'{sources,weights}'IS DISTINCT FROM '[]'::jsonb OR context#>'{sources,tasks}'IS DISTINCT FROM '[]'::jsonb OR context#>>'{sources,assessment,id}'IS DISTINCT FROM assessment_id::text THEN RAISE EXCEPTION 'Actual context lost full independent originals or inferred clinical sources';END IF;
  capture_packet:=jsonb_build_object('schemaVersion','1','requestId',capture_id,'tenantId',t,'clientId',c,'actorId',u,'planVersionId',version_id,'measureId',item_id,'visitId',stop_id,'assessmentId',assessment_id,'kind','drink_protocol','title','Synthetic explicitly planned drink support','plannedAt',at_text,'nativeOriginals',context->'nativeOriginals','sources',context->'sources');
  BEGIN PERFORM public.web_capture_nutrition_elimination_plan_binding(capture_packet||jsonb_build_object('requestId','A0000000-0000-4000-8000-000000000001'));RAISE EXCEPTION 'Noncanonical capture ID accepted';EXCEPTION WHEN check_violation THEN alias_denials:=alias_denials+1;END;
  IF EXISTS(SELECT 1 FROM public.nutrition_elimination_plan_bindings WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM care_private.nutrition_binding_captures WHERE tenant_id=t)THEN RAISE EXCEPTION 'Rejected capture left partial rows';END IF;
  capture_receipt:=public.web_capture_nutrition_elimination_plan_binding(capture_packet);
  capture_confirmed:=public.web_confirm_nutrition_elimination_plan_binding(t,c,u,capture_id,capture_packet);
  IF capture_receipt->'packet'IS DISTINCT FROM capture_packet OR capture_receipt#>'{binding,nativeOriginals}'IS DISTINCT FROM native_before OR capture_receipt#>'{binding,planSnapshotSha256}'IS DISTINCT FROM context->'planSnapshotSha256'OR capture_confirmed IS DISTINCT FROM capture_receipt THEN RAISE EXCEPTION 'Exact capture original/confirmation failed';END IF;
  entry:=jsonb_build_object('kind','drink_protocol','title',capture_packet->'title','plannedAt',at_text,'occurredAt',null,'planVersionId',version_id,'measureId',item_id,'visitId',stop_id,'assessmentId',assessment_id,'planSnapshotSha256',context->'planSnapshotSha256',
   'decision','{"state":"not_asked","recordedAt":null,"reason":"","consultation":""}'::jsonb,
   'assistance','{"level":"independent","helpers":[],"aids":[],"details":""}'::jsonb,
   'intake','{"offered":null,"actual":null,"unit":"none","item":"Synthetic planned water support","dietForm":"","target":null,"targetUnit":"none"}'::jsonb,
   'elimination','{"input":null,"output":null,"unit":"none","complete":false,"profileId":null,"support":"","stool":"","observation":""}'::jsonb,
   'swallowing','{"approvedDiet":"","instruction":"","deviation":"","escalation":""}'::jsonb,
   'enteral','{"deviceId":null,"prescriptionId":null,"product":"","amount":null,"unit":"none","durationMinutes":null,"flushMl":null,"positionCheck":"","skin":"","tolerance":""}'::jsonb,
   'device','{"deviceId":null,"changeBasisId":null,"type":"none","materialChange":"","skin":"","positionCheck":"","output":"","complication":""}'::jsonb,
   'weight','{"value":null,"unit":"none","measurementId":null,"instrumentVersion":"","conditions":"","professionalAssessment":"","reaction":"","reviewAt":null}'::jsonb,
   'execution','{"outcome":"planned","performedBy":[],"result":"","deviation":""}'::jsonb,
   'followUp','{"required":false,"reason":"","responsibleProfileId":null,"dueAt":null,"taskId":null,"state":"not_required","closureEvidence":""}'::jsonb,'lifecycle','open');
  packet:=jsonb_build_object('schemaVersion','1','action','create','requestId',care_id,'tenantId',t,'clientId',c,'actorId',u,'expectedHeadId',null,'expectedRevision',0,'entry',entry,'reason','','original',null,'sources',context->'sources');
  BEGIN PERFORM public.web_commit_nutrition_elimination_packet(packet||jsonb_build_object('requestId','A0000000-0000-4000-8000-000000000002'));RAISE EXCEPTION 'Noncanonical care ID accepted';EXCEPTION WHEN check_violation THEN alias_denials:=alias_denials+1;END;
  IF EXISTS(SELECT 1 FROM public.nutrition_elimination_roots WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_elimination_events WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_elimination_receipts WHERE tenant_id=t)THEN RAISE EXCEPTION 'Rejected care left partial rows';END IF;
  receipt:=public.web_commit_nutrition_elimination_packet(packet);confirmed:=public.web_confirm_nutrition_elimination_packet(t,c,u,care_id,packet);
  IF receipt->'packet'IS DISTINCT FROM packet OR receipt#>'{original,payload}'IS DISTINCT FROM entry OR confirmed IS DISTINCT FROM receipt THEN RAISE EXCEPTION 'Exact planned care/confirmation failed';END IF;
  review_packet:=jsonb_build_object('schemaVersion','1','action','request','requestId',review_id,'tenantId',t,'clientId',c,'actorId',u,'expectedHeadId',null,'expectedRevision',0,'careOriginal',receipt->'original','reviewOriginal',null,'reason','Synthetic explicit inspection of open planning, no clinical decision','requiredChange','','rationale','');
  BEGIN PERFORM public.web_commit_nutrition_review(review_packet||jsonb_build_object('requestId','A0000000-0000-4000-8000-000000000003'));RAISE EXCEPTION 'Noncanonical review ID accepted';EXCEPTION WHEN check_violation THEN alias_denials:=alias_denials+1;END;
  IF EXISTS(SELECT 1 FROM public.nutrition_review_roots WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_review_events WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_review_receipts WHERE tenant_id=t)THEN RAISE EXCEPTION 'Rejected review left partial rows';END IF;
  review_receipt:=public.web_commit_nutrition_review(review_packet);review_confirmed:=public.web_confirm_nutrition_review(t,c,u,review_id,review_packet);
  IF review_receipt->'packet'IS DISTINCT FROM review_packet OR review_receipt#>>'{original,status}'IS DISTINCT FROM 'requested'OR review_receipt#>>'{original,careRootId}'IS DISTINCT FROM receipt#>>'{original,rootId}'OR review_receipt#>>'{original,careHeadId}'IS DISTINCT FROM receipt#>>'{original,headId}'OR review_receipt#>>'{original,careFingerprint}'IS DISTINCT FROM receipt#>>'{original,contentFingerprint}'OR review_receipt#>'{original,history,0,qualification}'IS DISTINCT FROM 'null'::jsonb OR review_confirmed IS DISTINCT FROM review_receipt OR public.web_commit_nutrition_review(review_packet)IS DISTINCT FROM review_receipt THEN RAISE EXCEPTION 'Own exact technical review/confirmation failed';END IF;
  BEGIN PERFORM public.web_confirm_nutrition_review(t,c,u,gen_random_uuid(),review_packet);RAISE EXCEPTION 'Unknown review adopted receipt';EXCEPTION WHEN SQLSTATE 'P0G03'THEN NULL;END;
  BEGIN PERFORM public.web_commit_nutrition_review(review_packet||jsonb_build_object('reason','Synthetic changed request reuse'));RAISE EXCEPTION 'Own frozen review request rewritten';EXCEPTION WHEN serialization_failure THEN NULL;END;
  bad:=jsonb_set(review_packet||jsonb_build_object('requestId',gen_random_uuid()),'{careOriginal,payload,title}','"Synthetic substituted planning original"');
  BEGIN PERFORM public.web_commit_nutrition_review(bad);RAISE EXCEPTION 'Substituted care original adopted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  claims:=current_setting('request.jwt.claims');
  INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data)VALUES(reviewer,reviewer||'@example.invalid','{}','{}');
  UPDATE public.profiles SET tenant_id=t,role_id=r,role_key='pfleger',is_active=true,status='active',display_name='Synthetic independent technical inspector'WHERE id=reviewer;
  INSERT INTO auth.sessions(id,user_id,not_after)VALUES(review_session,reviewer,clock_timestamp()+interval'1 hour');
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',reviewer,'role','authenticated','session_id',review_session,'exp',extract(epoch FROM clock_timestamp()+interval'1 hour')::bigint)::text,true);
  IF public.resolve_current_profile_id()IS DISTINCT FROM reviewer OR public.current_tenant_id()IS DISTINCT FROM t OR care_private.nutrition_own_permission('pflege.documentation.sign')IS DISTINCT FROM true THEN RAISE EXCEPTION 'Independent current sign-role control missing';END IF;
  PERFORM care_private.nutrition_elimination_actor(t,c,reviewer,false);
  BEGIN PERFORM public.web_confirm_nutrition_review(t,c,reviewer,review_id,review_packet);RAISE EXCEPTION 'Independent account adopted authors receipt';EXCEPTION WHEN SQLSTATE 'P0G03'THEN NULL;END;
  FOREACH field IN ARRAY ARRAY['accept','return']LOOP
   bad:=review_packet||jsonb_build_object('action',field,'requestId',gen_random_uuid(),'actorId',reviewer,'expectedHeadId',review_receipt#>'{original,headId}','expectedRevision',1,'reviewOriginal',review_receipt->'original','reason','Synthetic decision denial control','requiredChange',CASE WHEN field='return'THEN 'Synthetic requested change'ELSE ''END,'rationale','Synthetic proposed rationale; no clinical authority claimed');
   BEGIN PERFORM public.web_commit_nutrition_review(bad);RAISE EXCEPTION 'Clinical decision accepted';EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS message=MESSAGE_TEXT;IF message NOT LIKE 'Klinische Annahme/Rückgabe bleibt%'THEN RAISE EXCEPTION 'Denial did not reach explicit clinical closure: %',message;END IF;clinical_denials:=clinical_denials+1;END;
  END LOOP;
  PERFORM set_config('request.jwt.claims',claims,true);
  prerequisites:=public.web_read_nutrition_elimination_prerequisites(t,c,u);care_page:=public.web_read_nutrition_elimination_page(t,c,u,null,null,100);review_page:=public.web_read_nutrition_review_page(t,c,u,null,null,100);
  care_tail:=public.web_read_nutrition_elimination_page(t,c,u,(care_page->>'nextCursorRecordedAt')::timestamptz,(care_page->>'nextCursorId')::uuid,100);
  review_tail:=public.web_read_nutrition_review_page(t,c,u,(review_page->>'nextCursorRecordedAt')::timestamptz,(review_page->>'nextCursorId')::uuid,100);
  IF care_tail->'rows'IS DISTINCT FROM '[]'::jsonb OR care_tail->'nextCursorId'IS DISTINCT FROM 'null'::jsonb OR care_tail->'nextCursorRecordedAt'IS DISTINCT FROM 'null'::jsonb OR care_tail->'stateFingerprint'IS DISTINCT FROM prerequisites->'stateFingerprint'OR care_page->'rows'IS DISTINCT FROM jsonb_build_array(receipt->'original')OR review_page->'rows'IS DISTINCT FROM jsonb_build_array(review_receipt->'original')OR review_tail->'rows'IS DISTINCT FROM '[]'::jsonb OR review_tail->'nextCursorId'IS DISTINCT FROM 'null'::jsonb OR review_tail->'nextCursorRecordedAt'IS DISTINCT FROM 'null'::jsonb OR care_page->'stateFingerprint'IS DISTINCT FROM prerequisites->'stateFingerprint'OR review_page->'stateFingerprint'IS DISTINCT FROM prerequisites->'stateFingerprint'OR review_tail->'stateFingerprint'IS DISTINCT FROM prerequisites->'stateFingerprint'THEN RAISE EXCEPTION 'Whole joined page state or empty terminator missing';END IF;
  IF alias_denials<>3 OR clinical_denials<>2 OR(SELECT count(*)FROM public.nutrition_elimination_events WHERE tenant_id=t)<>1 OR(SELECT count(*)FROM public.nutrition_review_events WHERE tenant_id=t)<>1 OR(SELECT count(*)FROM public.nutrition_review_receipts WHERE tenant_id=t)<>1 OR public.web_read_nutrition_elimination_binding_context(t,c,u,version_id,item_id,stop_id,assessment_id)IS DISTINCT FROM context THEN RAISE EXCEPTION 'Denied/repeated calls changed complete native originals or appended events';END IF;
  finished:=true;RAISE EXCEPTION USING ERRCODE='Z0001';
 EXCEPTION WHEN SQLSTATE'Z0001'THEN NULL;END;
 IF finished IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM public.tenants WHERE id=t)OR EXISTS(SELECT 1 FROM auth.users WHERE id IN(u,reviewer))OR EXISTS(SELECT 1 FROM auth.sessions WHERE id IN(s,review_session))OR EXISTS(SELECT 1 FROM public.profiles WHERE id IN(u,reviewer))OR EXISTS(SELECT 1 FROM public.roles WHERE id=r)OR EXISTS(SELECT 1 FROM public.role_permissions WHERE role_id=r)OR EXISTS(SELECT 1 FROM public.role_permission_sets WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.clients WHERE id=c)OR EXISTS(SELECT 1 FROM public.client_module_assignments WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.care_plans WHERE id=plan_id)OR EXISTS(SELECT 1 FROM public.care_plan_items WHERE id=item_id)OR EXISTS(SELECT 1 FROM public.care_plan_versions WHERE id=version_id)OR EXISTS(SELECT 1 FROM public.care_tours WHERE id=tour_id)OR EXISTS(SELECT 1 FROM public.care_tour_stops WHERE id=stop_id)OR EXISTS(SELECT 1 FROM public.care_assessments WHERE id=assessment_id)OR EXISTS(SELECT 1 FROM public.care_assessment_topics WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.care_assessment_risks WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.care_assessment_measures WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_elimination_plan_bindings WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM care_private.nutrition_binding_captures WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_elimination_roots WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_elimination_events WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_elimination_receipts WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_review_roots WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_review_events WHERE tenant_id=t)OR EXISTS(SELECT 1 FROM public.nutrition_review_receipts WHERE tenant_id=t)THEN RAISE EXCEPTION 'Supplementary Nutrition full inner rollback cleanup failed';END IF;
 PERFORM set_config('cp365.nutrition_linked_inspection',jsonb_build_object('schemaVersion',1,'supplementaryRuntimeUnit',true,'cleanupConfirmed',true,'linkedPlannedInspection',true,'canonicalAliasDenials',alias_denials,'clinicalDecisionDenials',clinical_denials,'expected',jsonb_build_object('tenantId',t,'clientId',c,'actorId',u,'reviewerId',reviewer,'planVersionId',version_id,'measureId',item_id,'visitId',stop_id,'assessmentId',assessment_id,'captureRequestId',capture_id,'careRequestId',care_id,'reviewRequestId',review_id),'context',context,'capturePacket',capture_packet,'captureReceipt',capture_receipt,'captureConfirmed',capture_confirmed,'carePacket',packet,'careReceipt',receipt,'careConfirmed',confirmed,'reviewPacket',review_packet,'reviewReceipt',review_receipt,'reviewConfirmed',review_confirmed,'prerequisites',prerequisites,'carePage',care_page,'careTail',care_tail,'reviewPage',review_page,'reviewTail',review_tail)::text,true);
END $unit$;
SELECT current_setting('cp365.nutrition_linked_inspection',true)::jsonb AS synthetic_evidence;
ROLLBACK;
